import{benchmarkBand}from'./onet-benchmark-057.js';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Unavailable';
let report,catalog,byId,index,strongByModel=new Map(),page=0,filtered=[],careerRows=[],careerFocus='',chunks=new Map();const holdouts=['holdout','holdout049','holdout056'],dev=r=>!holdouts.includes(r.phase),phaseScope=r=>{const p=$('cohort').value;return p==='all'||p==='development'&&dev(r)||p==='original'&&!r.phase.endsWith('056')||p==='added'&&r.phase.endsWith('056')||r.phase===p;},route=c=>{const p=$('education').value;return p==='all'||c.routes.some(r=>p==='degree'?['college','graduate'].includes(r.key):r.key===p);},degree=id=>byId.get(id).routes.some(r=>['college','graduate'].includes(r.key));
const names=ids=>ids.map(id=>byId.get(id)?.title).join('; '),chip=(id,blue=false)=>'<span class="chip '+(blue?'blue':'')+'">'+h(byId.get(id).title)+'</span>',count=(n,d)=>n+' / '+d+'<small>'+Math.round(100*n/d)+'% of models</small>',pair=(a,b,n)=>'<strong>'+a+' → <span class="delta">'+b+'</span></strong><small>'+Math.round(100*a/n)+'% → '+Math.round(100*b/n)+'%</small>';
async function fetchJSON(url){const response=await fetch(url);if(!response.ok)throw Error('Benchmark data could not load.');let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());return JSON.parse(new TextDecoder().decode(bytes));}
async function getModel(item){if(!chunks.has(item.part))chunks.set(item.part,(async()=>{const response=await fetch(report.parts[item.part].url);if(!response.ok)throw Error('Model comparison could not load.');let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());return JSON.parse(new TextDecoder().decode(bytes));})());return(await chunks.get(item.part)).find(r=>r.id===item.id);}
function summaryHTML(s){return'<tr><td><strong>'+h(s.label)+'</strong><small>'+s.models+' models</small></td><td>'+pair(s.currentTop,s.strong,s.models)+'</td><td>'+pair(s.currentDegreeTop,s.degreeStrong,s.models)+'</td><td>'+pair(s.currentTopCovers,s.strongCovers,s.models)+'</td><td>'+count(s.union,s.models)+'<small>'+s.unionDegree+' with a degree route</small></td><td>'+count(s.noContraryDegreeStrong,s.models)+'</td><td>'+s.unscorable+'<small>'+s.nearFlat+' near-flat</small></td><td>'+s.strongContraryModels+' models<small>'+s.strongContraryOffers+' / '+s.strongOffers+' strong offers</small></td></tr>';}
function initSummary(){const groups=[{label:'Development · all five development groups',...report.summary.development},...holdouts.map(p=>({label:report.phaseLabels[p],...report.summary.cohorts.find(s=>s.phase===p)}))];$('coverage').innerHTML='<table class="review-table"><thead><tr><th>Cohort</th><th>Any: current Top → Best/Great</th><th>Bachelor’s/graduate: current Top → Best/Great</th><th>First-paid-stage lifestyle coverage: current Top → Best/Great</th><th>Keep current Top + add strong exploration</th><th>Degree connection with no recorded contrary answer</th><th>Unscorable for interest matching</th><th>Some strong results conflict with specific answers</th></tr></thead><tbody>'+groups.map(summaryHTML).join('')+'</tbody></table>';
 $('coverage-note').textContent='The combined column preserves current Top and adds interest-led invitations; it does not promote those invitations to Top. Interest-led coverage is broader than profession confirmation. No recorded contrary answer can also mean that no specific question was answered. Missing first-paid-stage pay stays unassessed; occupational medians never establish lifestyle coverage.';
 const orig=index.filter(r=>!r.phase.endsWith('056')),added=index.filter(r=>r.phase.endsWith('056'));$('construction').innerHTML='<strong>Keep model construction in mind.</strong> Original '+orig.length+' life-first profiles and '+added.length+' procedurally expanded profiles are shown separately in the cohort filter. '+report.scope.diagnosticExcluded+' diagnostic variants and '+report.scope.privateExcluded+' owner-only cases are excluded. Holdouts were fixed earlier, but their previous aggregate results have been seen. No thresholds were tuned on this run.';
 renderRouteBars();
 $('method-content').innerHTML='<div class="notice"><strong>Interpretation: expand discovery; retain a separate evidence status.</strong> Stronger coverage does not establish a better confirmed Top. Our six selected development examples show that broad arts/social interests can surface therapy and college teaching without distinctive interest evidence. Some current specifically supported careers also have lower whole-profile similarity. A future hybrid should preserve both kinds of evidence and honor specific negatives.</div><details><summary>Six development examples · qualitative spot check</summary><p>'+h(report.developmentReview.scope)+'</p>'+report.developmentReview.rows.map(v=>'<article><h3><a href="./onet-benchmark.html?model='+v.modelId+'">'+h(v.name)+' →</a></h3><p><strong>Profile evidence:</strong> '+h(v.evidence)+'</p><p>'+h(v.assessment)+'</p><p><strong>Implication:</strong> '+h(v.action)+'</p></article>').join('')+'</details><ul>'+report.interpretation.map(t=>'<li>'+h(t)+'</li>').join('')+'</ul><p><strong>Official-rule implementation:</strong> Both approaches already use the same six-score Pearson formula where comparable. The benchmark changes discovery eligibility and list construction. It correlates the six original RIASEC totals with occupation vectors. Best ≥ 0.729; Great ≥ 0.608; Good ≥ 0. All Best/Great results are returned per Job Zone; if fewer than ten, nonnegative Good results fill toward ten. No upper cap; alphabetical within fit band. Education and income never change the interest score. The comparison matrix regroups returned careers by education route, with current Top first and remaining careers by correlation. This is a catalog-constrained reproduction, not a fresh call to the full official service for each model.</p><p><strong>Inventory:</strong> '+report.scope.catalog+' careers; '+report.scope.vectors+' have usable six-interest vectors; '+report.scope.wages+' have occupational wage references; '+report.scope.firstPaidStage+' have an existing first-paid-stage/proxy figure. '+report.scope.withoutVector.length+' lack comparable vectors: '+h(names(report.scope.withoutVector))+'. Missing data is not a mismatch.</p><p><strong>Education-label reconciliation:</strong> The live chart’s “degree” flag includes some associate routes and misses one doctoral profile. Some expanded specialty preparation labels also use a broader BLS occupation and require profession-level verification. Its unchanged count is '+report.policy.baselineCounts.degreeTop+' / 1,000. This benchmark consistently groups catalog bachelor’s/graduate routes on both sides ('+report.summary.all.currentDegreeTop+' current). Associate degrees remain visible under community college. No live labels or matching have been changed.</p><p><strong>Inventory balance:</strong> '+catalog.filter(c=>c.routes.some(r=>['college','graduate'].includes(r.key))).length+' of '+catalog.length+' catalog careers have a bachelor’s/graduate route ('+catalog.filter(c=>c.vector&&c.routes.some(r=>['college','graduate'].includes(r.key))).length+' of '+report.scope.vectors+' scorable careers). The degree-heavy pool gives more chances to find a strong degree connection. Both sides use that same inventory; higher degree coverage is not proof of greater student preference for college.</p><p><strong>Current-rule decomposition:</strong> '+report.summary.all.currentAllDegreeSupported+' models have some specifically supported bachelor’s/graduate career before the three-Top display cap, versus '+report.summary.all.currentDegreeTop+' in the three shown. '+report.summary.all.currentTopStrongOffers+' of '+report.summary.all.currentTopOffers+' current Top offers are also O*NET Best/Great. Specific fit and broad six-interest similarity can disagree.</p><p><strong>Near-flat sensitivity:</strong> keeping the current profile guard gives '+report.summary.all.strong+' / 1,000 any strong and '+report.summary.all.degreeStrong+' / 1,000 strong degree connections. Allowing complete nonflat near-flat profiles gives '+report.summary.all.manualSensitivityStrong+' and '+report.summary.all.manualSensitivityDegree+' respectively. This is reported separately, not used to inflate the primary comparison. Flat profiles have undefined Pearson correlation.</p><p><strong>Wages:</strong> existing first-paid-stage figures retain their source/assumption labels. Additional 2025 Austin occupational medians and wage-group means are descriptive only, with Texas statewide fallback labeled. The lower-paid third and upper-paid two-thirds are worker wage groups, not experience years. Specialist SOCs can share a broader wage group. Related experience can be required before entry into the occupation. All figures exclude tuition and imply no guarantee.</p><p><strong>Validation:</strong> frozen input and live engine fingerprints, unchanged current replay ID, independent six-score arithmetic in the downloadable notebook, edge-case and split tests. This tests implementation and coverage, not predictive accuracy, aptitude or student satisfaction. The 828 procedural profiles still depend on authored answer bindings; this benchmark avoids those bindings for O*NET scoring but does not independently validate the underlying synthetic profiles.</p><p>Current replay fingerprint: <code>'+h(report.currentRunId)+'</code></p>';
}
function renderRouteBars(){const phase=$('route-cohort').value;$('route-bars').innerHTML='<div class="legend"><span>Current supported Top</span><span>O*NET Best / Great</span></div>'+report.routeSummary.map(r=>{const c=r[phase];return'<div class="route-row"><button data-route="'+r.key+'">'+h(r.title)+' →</button><div class="bar-pair"><div class="bar" style="width:'+100*c.current/c.models+'%"></div><div class="bar onet" style="width:'+100*c.onet/c.models+'%"></div></div><div class="route-numbers">'+c.current+' / '+c.models+'<br><b>'+c.onet+' / '+c.models+'</b></div></div>';}).join('');}
function render(){page=0;careerFocus='';renderModels();renderCareers();}
function renderModels(){const scope=index.filter(phaseScope),q=$('query').value.trim().toLowerCase(),review=$('review').value;
 const allowed=new Set(catalog.filter(route).map(c=>c.id)),careerQuery=new Set(catalog.filter(c=>[c.title,c.id,c.soc].some(v=>v.toLowerCase().includes(q))).map(c=>c.id));
 filtered=scope.filter(r=>{const strong=strongByModel.get(r.id)||[],inRoute=[...r.top,...strong].filter(id=>allowed.has(id));return (!careerFocus||r.top.includes(careerFocus)||strong.includes(careerFocus))&&(!q||[r.id,r.name].some(v=>v.toLowerCase().includes(q))||inRoute.some(id=>careerQuery.has(id)))&&(review==='all'||review==='recovered'&&!r.top.length&&r.strongCount||review==='degree'&&!r.topDegree&&r.strongDegree||review==='conflict'&&r.conflicts||review==='unscorable'&&(!r.eligible||!r.strongCount))&&($('education').value==='all'||inRoute.length);});
 $('scope-note').textContent=($('cohort').selectedOptions[0].textContent)+'. Summary cards use the whole selected cohort; the table also applies review, education and search filters. All education routes are selected initially.';
 const metric=(n,label)=>'<div class="metric"><b>'+n+' / '+scope.length+'</b><span>'+label+'</span></div>';$('model-summary').innerHTML=metric(scope.filter(r=>r.top.length).length,'Current supported Top')+metric(scope.filter(r=>r.strongCount).length,'Best / Great interest connection')+metric(scope.filter(r=>r.topDegree).length,'Current bachelor’s / graduate Top')+metric(scope.filter(r=>r.strongDegree).length,'Best / Great bachelor’s / graduate');
 $('model-count').textContent=filtered.length+' matching models'+(careerFocus?' · '+byId.get(careerFocus).title:'');const n=Math.max(1,Math.ceil(filtered.length/30));page=Math.min(page,n-1);$('page').textContent='Page '+(page+1)+' of '+n;$('previous').disabled=page===0;$('next').disabled=page>=n-1;
 $('model-rows').innerHTML=filtered.slice(page*30,page*30+30).map(r=>'<tr><td><button class="primary" data-model="'+r.id+'">'+h(r.name)+'</button><small>'+h(r.id)+'<br>'+h(report.phaseLabels[r.phase])+'</small><a href="./model-lab.html?case='+encodeURIComponent(r.id)+'">Profile & saved answers →</a></td><td><div class="chips">'+(r.top.filter(id=>route(byId.get(id))).map(id=>chip(id)).join('')||'<span class="muted">No Top in this route</span>')+'</div><small>'+(r.topCovers?'Across all routes: current Top covers first-paid-stage lifestyle':'Across all routes: no current Top covers first-paid-stage lifestyle')+'</small></td><td><strong>'+(r.routeCounts?.[$('education').value]??r.strongCount)+' Best / Great in selected route</strong><div class="chips">'+(r.preview?.[$('education').value]||[]).map(id=>chip(id,true)).join('')+'</div><small>'+r.bestCount+' Best across all routes · '+(r.strongDegree?'includes bachelor’s/graduate routes':'no strong bachelor’s/graduate route')+'</small><small>'+(r.strongCovers?'Across all routes: a strong connection covers the first-paid-stage budget':'Across all routes: no assessed strong connection covers the first-paid-stage budget')+'</small><button data-model="'+r.id+'">Compare every career & earnings →</button></td><td>'+(r.conflicts?'<p class="warn">'+r.conflicts+' strong careers have specific contrary answers</p>':'<small>No recorded contrary answers among strong results</small>')+(!r.eligible?'<p class="warn">'+(r.nearFlat?'Near-flat profile: primary guard retained':'Flat or incomplete profile: correlation unavailable')+'</p>':'')+'<small>'+r.topStrongOverlap+' / '+r.top.length+' current Top also Best / Great</small></td></tr>').join('')||'<tr><td colspan="4" class="empty">No models meet these filters.</td></tr>';
}
// Small inverted index supports exact model/career filtering without loading every detailed chunk.
function strongMember(r,id){return report.membership[id]?.includes(r.id);}
function renderCareers(){const scoped=index.filter(phaseScope),ids=new Set(scoped.map(r=>r.id)),q=$('query').value.trim().toLowerCase();careerRows=catalog.filter(route).filter(c=>!q||[c.title,c.id,c.soc].some(s=>s.toLowerCase().includes(q))).map(c=>{const strong=(report.membership[c.id]||[]).filter(id=>ids.has(id)).length,top=scoped.filter(r=>r.top.includes(c.id)).length,contrary=(report.contraryMembership[c.id]||[]).filter(id=>ids.has(id)).length;return{...c,strong,top,contrary};}).sort((a,b)=>b.strong-a.strong||b.top-a.top||a.title.localeCompare(b.title));$('career-count').textContent=careerRows.length+' careers · '+scoped.length+' models · '+careerRows.filter(c=>!c.strong&&!c.top).length+' with neither current Top nor strong interest appearances';
 $('career-rows').innerHTML=careerRows.map(c=>'<tr><td><button data-career="'+c.id+'"><strong>'+h(c.title)+'</strong></button><small>'+h(c.routes.map(r=>r.label).join(' / '))+' · Job Zone '+(c.zone||'unclassified')+(c.requiresExperience?' · Related experience needed':'')+'</small>'+(c.educationCaution?'<small>'+h(c.educationCaution)+'</small>':'')+'<a href="'+h(c.sourceURL)+'" target="_blank" rel="noopener">Occupation source ↗</a></td><td>'+c.top+'</td><td><strong class="delta">'+c.strong+'</strong></td><td>'+c.contrary+'</td><td>'+money(c.first?.amount)+'<small>'+h(c.first?.label||'Not established')+' · '+h(c.first?.basis||c.firstPayCaution||'')+'</small></td><td>'+money(c.wage?.median)+'<small>'+h(c.wage?.area||'No wage record')+' · '+h(c.wage?.period||'')+(c.wage?.broader?' · Broader SOC group':'')+'</small>'+(c.wage?'<a href="'+h(c.wage.sourceURL)+'" target="_blank" rel="noopener">Wage source ↗</a>':'')+'</td><td>'+money(c.wage?.lowerThird)+' → '+money(c.wage?.upperTwoThirds)+'<small>Means of worker wage groups; not years of experience</small></td></tr>').join('');
}
async function openModel(id){const item=index.find(r=>r.id===id);$('model-detail').innerHTML='<h2 id="detail-title">Loading model comparison…</h2>';$('model-dialog').showModal();try{const r=await getModel(item),visible=new Set([...r.selected,...r.supported,...r.first12]),scored=new Map(catalog.map((c,i)=>[c.id,r.scores[i]]));
 const careerRow=c=>{const score=scored.get(c.id),selected=r.selected.includes(c.id),strong=r.strong.includes(c.id),current=r.top.includes(c.id)?'Current Top':r.supported.includes(c.id)?'Supported · outside Top 3':r.first12.includes(c.id)?'Current Other / invitation':'Not specifically confirmed',contra=r.contrary[c.id]||[],held=r.holds[c.id]||[];
 return'<tr><td><strong>'+h(c.title)+'</strong><small>'+h(c.soc)+' · Job Zone '+(c.zone||'unclassified')+(c.requiresExperience?' · Requires related experience':'')+'</small>'+(c.educationCaution?'<small>'+h(c.educationCaution)+'</small>':'')+'<a href="'+h(c.sourceURL)+'" target="_blank" rel="noopener">Occupation source ↗</a></td><td><span class="chip">'+current+'</span></td><td><span class="chip '+(strong?'blue':'')+'">'+(r.eligible?selected?benchmarkBand(score)+' interest fit':'Not returned by interest baseline':'Primary profile guard')+'</span><small>Pearson r = '+(score===null?'unavailable':score.toFixed(3))+'</small>'+(selected&&!strong?'<small>Good filler; excluded from strong coverage</small>':'')+'</td><td>'+money(c.first?.amount)+'<small>'+h(c.first?.label||'Not established')+' · '+h(c.first?.basis||'')+'</small><small>First-paid-stage lifestyle: <strong>'+(r.coverage[c.id]===true?'Covers under current assumptions':r.coverage[c.id]===false?(c.requiresExperience?'Experienced destination; not entry coverage':'Does not cover'):'Unassessed')+'</strong></small>'+(c.stages.length?'<details><summary>Pay stages & source labels</summary>'+c.stages.map(s=>'<p>'+h(s.label)+': '+money(s.amount)+'<small>'+h(s.basis)+' · '+h(s.period||'')+'</small></p>').join('')+'</details>':'')+'</td><td>'+money(c.wage?.median)+'<small>'+h(c.wage?.area||'Unavailable')+' · '+h(c.wage?.period||'')+(c.wage?.broader?' · Broader SOC; not specialty-specific':'')+'</small><small>Lower-third mean: '+money(c.wage?.lowerThird)+'<br>Upper-two-thirds mean: '+money(c.wage?.upperTwoThirds)+'</small>'+(c.wage?'<a href="'+h(c.wage.sourceURL)+'" target="_blank" rel="noopener">Wage source ↗</a>':'')+'</td><td class="evidence">'+(contra.length?'<strong class="warn">Specific answer disagrees</strong>'+contra.map(q=>'<p>'+h(q.prompt)+'<small>Answer: No · '+h(q.source)+'<br>'+h(q.evidence)+'</small></p>').join(''):'No recorded specific No. Missing confirmation is not a positive answer.')+(held.length?'<p class="warn">'+held.map(q=>h(q.reason)).join('<br>')+'</p>':'')+'</td></tr>';};
 $('model-detail').innerHTML='<h2 id="detail-title">'+h(r.name)+'</h2><p>'+h(r.id)+' · '+h(report.phaseLabels[r.phase])+' · <a href="./model-lab.html?case='+encodeURIComponent(r.id)+'">Full profile & every saved answer →</a> · <a href="./model-match-chart.html?query='+encodeURIComponent(r.id)+'">Current match evidence →</a></p><div class="score-grid">'+['Realistic','Investigative','Artistic','Social','Enterprising','Conventional'].map((t,i)=>'<div>'+t.slice(0,1)+'<b>'+h(r.raw[i]??'—')+'</b><small>'+t+'</small></div>').join('')+'</div><p class="small">Original 60-question interest totals, each out of 40. Interest scores do not measure skills or aptitude. '+r.answered+' / 60 answered.</p><p class="notice">'+r.top.length+' current Top · '+r.supported.length+' specifically supported before the display cap · '+r.strong.length+' Best / Great interest connections · '+(r.selected.length-r.strong.length)+' Good fillers. All five education routes are shown below, including the current Other invitations. A career with alternative routes can appear twice; no additional pay premium is assumed.</p>'+(!r.eligible?'<p class="warn">'+(r.nearFlat?'Near-flat: primary comparison retains the live guard. Manual-eligibility sensitivity has '+r.manualStrong.length+' strong connections.':'Flat or incomplete profile: Pearson comparison is undefined. Current specifically supported options can still appear.')+'</p>':'')+report.educationRouteGroups.map(g=>{const list=catalog.filter(c=>visible.has(c.id)&&c.routes.some(x=>x.key===g.id)).sort((a,b)=>(r.top.includes(b.id)?1:0)-(r.top.includes(a.id)?1:0)||(scored.get(b.id)??-2)-(scored.get(a.id)??-2)||a.title.localeCompare(b.title));return'<section><h3>'+h(g.title)+' · '+list.length+'</h3><p class="small">'+h(g.copy)+'</p>'+(list.length?'<div class="scroll"><table><thead><tr><th>Career</th><th>Current evidence status</th><th>O*NET-led interest result</th><th>First paid stage / lifestyle</th><th>Occupational earnings</th><th>Specific-answer cautions</th></tr></thead><tbody>'+list.map(careerRow).join('')+'</tbody></table></div>':'<p>No returned or currently supported career in this route.</p>')+'</section>';}).join('');
 }catch(e){$('model-detail').textContent=e.message;}}
function csv(file,columns,rows){const quote=s=>'"'+String(s??'').replaceAll('"','""')+'"',bytes=[columns.map(quote).join(','),...rows.map(r=>r.map(quote).join(','))].join('\r\n'),url=URL.createObjectURL(new Blob([bytes],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
try{report=await fetchJSON('./onet-benchmark/report.json.gz');catalog=report.catalog;byId=new Map(catalog.map(c=>[c.id,c]));index=report.index;for(const [id,models]of Object.entries(report.membership))for(const model of models){if(!strongByModel.has(model))strongByModel.set(model,[]);strongByModel.get(model).push(id);}for(const g of report.educationRouteGroups)$('education').insertAdjacentHTML('beforeend','<option value="'+g.id+'">'+h(g.title)+'</option>');initSummary();$('content').hidden=false;$('load-status').textContent='1,000 paired profiles loaded · benchmark only · live matching unchanged';render();const params=new URLSearchParams(location.search);if(params.has('cohort')&&[...$('cohort').options].some(o=>o.value===params.get('cohort'))){$('cohort').value=params.get('cohort');render();}if(params.has('model'))openModel(params.get('model'));}catch(e){$('load-status').textContent=e.message;}
for(const id of['cohort','education','review','query'])$(id).addEventListener(id==='query'?'input':'change',render);
document.addEventListener('click',e=>{const m=e.target.closest('[data-model]'),r=e.target.closest('[data-route]'),c=e.target.closest('[data-career]');if(m)openModel(m.dataset.model);if(r){$('cohort').value=$('route-cohort').value;$('education').value=r.dataset.route;render();$('models').scrollIntoView({behavior:'smooth'});}if(c){careerFocus=c.dataset.career;$('query').value='';$('review').value='all';page=0;renderModels();$('models').scrollIntoView({behavior:'smooth'});}});
$('previous').onclick=()=>{page--;renderModels();};$('next').onclick=()=>{page++;renderModels();};$('clear-search').onclick=()=>{$('query').value='';render();};
$('download-models').onclick=()=>csv('onet-benchmark-models.csv',['model_id','name','cohort','current_top','best_great_count','best_count','current_bachelor_graduate','strong_bachelor_graduate','specific_conflicting_careers','eligible'],filtered.map(r=>[r.id,r.name,r.phase,names(r.top),r.strongCount,r.bestCount,r.topDegree,r.strongDegree,r.conflicts,r.eligible]));
$('download-careers').onclick=()=>csv('onet-benchmark-careers.csv',['career_id','title','SOC','routes','job_zone','current_top_models','best_great_models','contrary_models','first_pay','first_pay_basis','occupational_median','lower_third_mean','upper_two_thirds_mean','geography','period','broader_wage_SOC','wage_source'],careerRows.map(c=>[c.id,c.title,c.soc,c.routes.map(r=>r.label).join('; '),c.zone,c.top,c.strong,c.contrary,c.first?.amount,c.first?.basis,c.wage?.median,c.wage?.lowerThird,c.wage?.upperTwoThirds,c.wage?.area,c.wage?.period,c.wage?.broader,c.wage?.sourceURL]));

$('route-cohort').addEventListener('change',renderRouteBars);

$('download-reproduction').onclick=async()=>{const button=$('download-reproduction');button.disabled=true;$('reproduction-status').textContent='Preparing all 1,000 public model results…';try{const rows=(await Promise.all(report.parts.map(p=>fetchJSON(p.url)))).flat(),data={catalog:report.catalog.map(c=>({id:c.id,title:c.title,zone:c.zone,vector:c.vector,routes:c.routes})),rows:rows.map(r=>({id:r.id,phase:r.phase,raw:r.raw,eligible:r.eligible,top:r.top,strong:r.strong,selected:r.selected,scores:r.scores}))},blob=await new Response(new Blob([JSON.stringify(data)]).stream().pipeThrough(new CompressionStream('gzip'))).blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='reproduction.json.gz';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('reproduction-status').textContent='Export ready: place reproduction.json.gz beside the notebook.';}catch(e){$('reproduction-status').textContent='Export did not finish. Please try again.';}finally{button.disabled=false;}};
